// recipe: console-rects
// args: none
// returns: ok, promptX, inputTextX, rowRingX, rowInkX, rowWidth, error, detail
//
// Reads the rects the console overlay DREW in its last frame (`CommandConsoleOverlay.Last*`), so the list's alignment with the
// caret is a measured number instead of an impression from a capture. `rowInkX` is where the first row's TEXT ink starts; the
// caret of the input sits at `inputTextX` plus the text field's own padding. No nested lambda: the Interactive host rejects one.
((System.Func<string>)(() => { var inv = System.Globalization.CultureInfo.InvariantCulture; var type = (System.Type)null; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < asms.Length; i++) { if (type == null) { try { type = asms[i].GetType("CasualtiesUnknownOnline.CommandConsoleOverlay", false); } catch { type = null; } } } if (type == null) { return "{\"ok\":false,\"error\":\"no-overlay-type\"}"; } var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public; var promptProperty = type.GetProperty("LastPromptRect", flags); var inputProperty = type.GetProperty("LastInputTextRect", flags); var ringProperty = type.GetProperty("LastSuggestionRect", flags); var inkProperty = type.GetProperty("LastSuggestionInkRect", flags); if (promptProperty == null || inputProperty == null || ringProperty == null || inkProperty == null) { return "{\"ok\":false,\"error\":\"no-rect-properties\"}"; } var prompt = (UnityEngine.Rect)promptProperty.GetValue(null); var inputText = (UnityEngine.Rect)inputProperty.GetValue(null); var ring = (UnityEngine.Rect)ringProperty.GetValue(null); var ink = (UnityEngine.Rect)inkProperty.GetValue(null); return "{\"ok\":true,\"promptX\":" + prompt.x.ToString("0.#", inv) + ",\"inputTextX\":" + inputText.x.ToString("0.#", inv) + ",\"rowRingX\":" + ring.x.ToString("0.#", inv) + ",\"rowInkX\":" + ink.x.ToString("0.#", inv) + ",\"rowWidth\":" + ring.width.ToString("0.#", inv) + "}"; }))()